  // Define the reducer function here
  type Action = { type: 'increment' } | { type: 'decrement' };
  const reducer = (state: number, action: Action): number => {
    switch (action.type) {
      case 'increment':
        return state + 1;
      case 'decrement':
        return state - 1;
      default:
        return state;
    }
  };

  // Initialize useReducer counter state here
  const [state, dispatch] = useReducer(reducer, 0);

  // Create useState increment handler here
  const incrementUseState = () => {
    setCount(count + 1);
  };

  // Create useState decrement handler here
  const decrementUseState = () => {
    setCount(count - 1);
  };

  return (
    <div>
      <h1>useState vs useReducer</h1>
      {/* Add two sections here: one for useState, one for useReducer */}
      <section>
        <h2>useState Counter</h2>
        <p>Count: {count}</p>
        {/* Add increment/decrement buttons for useState here */}
      </section>
      <section>
        <h2>useReducer Counter</h2>
        <p>Count: {state}</p>
        {/* Add increment/decrement buttons for useReducer here */}
      </section>
    </div>
  );
};

export default CounterComparison;
